      [2,"Hvor tykt skal laget være?","How thick should the layer be?","Какой толщины должен быть слой?","Якої товщини має бути шар?","Jak gruba ma być warstwa?","Cât de gros trebuie să fie stratul?","Kokio storio turi būti sluoksnis?","Колко дебел трябва да е слоят?"],
      [2,"Hvor finder jeg flere skruer?","Where can I find more screws?","Где взять ещё шурупы?","Де взяти ще шурупи?","Gdzie znajdę więcej wkrętów?","De unde iau mai multe șuruburi?","Kur rasti daugiau sraigtų?","Къде да намеря още винтове?"],
      [2,"Hvor skal affaldet hen?","Where does the waste go?","Куда девать мусор?","Куди подіти сміття?","Gdzie mam wyrzucić odpady?","Unde arunc deșeurile?","Kur dėti atliekas?","Къде се изхвърлят отпадъците?"],
      [2,"Hvilken farve skal der på?","Which colour should I use?","Какой краской красить?","Якою фарбою фарбувати?","Jakim kolorem mam malować?","Ce culoare folosesc?","Kokia spalva dažyti?","С какъв цвят да боядисвам?"],
      [2,"Skal jeg tage den ned?","Should I take it down?","Мне это снять?","Мені це зняти?","Mam to zdjąć?","Să-l dau jos?","Ar man tai nuimti?","Да го сваля ли?"],
      [2,"Må jeg låne din kniv?","Can I borrow your knife?","Можно взять твой нож?","Можна взяти твій ніж?","Mogę pożyczyć twój nóż?","Pot să-ți împrumut cuțitul?","Ar galiu pasiskolinti tavo peilį?","Може ли да ти взема ножа?"],
      [2,"Hvem arbejder jeg sammen med i dag?","Who am I working with today?","С кем я сегодня работаю?","З ким я сьогодні працюю?","Z kim dzisiaj pracuję?","Cu cine lucrez azi?","Su kuo šiandien dirbu?","С кого работя днес?"],
      [2,"Er det her den rigtige?","Is this the right one?","Это тот, что нужен?","Це той, що треба?","Czy to ten właściwy?","Ăsta e cel bun?","Ar čia tas, kurio reikia?","Това ли е правилният?"],
      [3,"Hvor er nøglen til skurvognen?","Where is the key to the site hut?","Где ключ от бытовки?","Де ключ від побутівки?","Gdzie jest klucz do kontenera socjalnego?","Unde e cheia de la baracă?","Kur vagonėlio raktas?","Къде е ключът за фургона?"],
      [3,"Hvornår kommer betonbilen?","When is the concrete truck coming?","Когда приедет миксер с бетоном?","Коли приїде міксер з бетоном?","Kiedy przyjedzie betonowóz?","Când vine autobetoniera?","Kada atvažiuos betonvežis?","Кога идва бетоновозът?"],
      [3,"Hvad hedder det her på dansk?","What is this called in Danish?","Как это называется по-датски?","Як це називається данською?","Jak to się nazywa po duńsku?","Cum se spune la asta în daneză?","Kaip tai vadinasi daniškai?","Как се казва това на датски?"]
